    40	                max: 100, quick: [0, 25, 50, 75, 100],
    41	                read: { qualifier().blur * 100 },
    42	                ops: { ops(ColorQualifierPatch(blur: $0 / 100)) },
    43	                mixed: { binding.mixedVideo { $0.qualifier.blur } }))
    44	        let pick = commandButton(
