    68	    /// One range's two rows: the checkbox and the strip, then the fields.
    69	    private func qualifierRows(
    70	        _ range: QualifierRange, read: @escaping () -> ColorQualifier,
    71	        ops: @escaping (ColorQualifierPatch) -> [ReelOp]
    72	    ) -> [NSView] {
    73	        let binding = self.binding
    74	        let name = range.title
    75	        func on() -> Bool { read().isOn(range) }
    76	        let check = OptionCheckboxControl(
    77	            label: name, read: on,
    78	            write: { [weak binding] value in
    79	                binding?.apply(name, ops(.toggle(range, value)))
    80	            },
    81	            enabled: { true },
    82	            onEdit: { [weak binding] in binding?.edited() })
    83	        check.translatesAutoresizingMaskIntoConstraints = false
    84	        check.widthAnchor.constraint(equalToConstant: InspectorMetrics.labelWidth).isActive = true
    85	        let strip = RangeStripControl(
    86	            kind: range, read: read,
    87	            begin: { [weak binding] in binding?.liveBegin() },
    88	            update: { [weak binding] patch in binding?.liveUpdate(ops(patch)) },
    89	            end: { [weak binding] in binding?.liveEnd(name) })
    90	        let mixed: () -> Bool
    91	        switch range {
    92	        case .hue: mixed = { binding.mixedVideo { $0.qualifier.hue } }
    93	        case .saturation: mixed = { binding.mixedVideo { $0.qualifier.saturation } }
