   104	
   105	    /// The range's three captioned fields across one row.
   106	    private func qualifierFields(
   107	        _ range: QualifierRange, read: @escaping () -> ColorQualifier,
   108	        ops: @escaping (ColorQualifierPatch) -> [ReelOp]
   109	    ) -> NSView {
   110	        let binding = self.binding
   111	        let name = range.title
   112	        func on() -> Bool { read().isOn(range) }
   113	        typealias Field = (caption: String, max: Double, get: (ColorQualifier) -> Double,
   114	                           put: (ColorQualifier, Double) -> ColorQualifierPatch)
   115	        let fields: [Field]
   116	        if range == .hue {
   117	            func hue(_ q: ColorQualifier) -> QualifierHue { q.hue ?? .initial }
   118	            fields = [
   119	                ("Centre", 360, { hue($0).center },
   120	                 { q, v in var h = hue(q); h.center = v; return ColorQualifierPatch(hue: .set(h)) }),
   121	                ("Width", 360, { hue($0).width },
   122	                 { q, v in var h = hue(q); h.width = v; return ColorQualifierPatch(hue: .set(h)) }),
   123	                ("Soft", 180, { hue($0).softness },
   124	                 { q, v in var h = hue(q); h.softness = v; return ColorQualifierPatch(hue: .set(h)) }),
   125	            ]
   126	        } else {
   127	            func levels(_ q: ColorQualifier) -> QualifierLevels { q.levels(range) ?? .initial }
   128	            fields = [
   129	                ("Low", 1, { levels($0).low },
   130	                 { q, v in
   131	                     var l = levels(q)
   132	                     l.low = min(v, l.high)
   133	                     return .levels(range, .set(l))
   134	                 }),
   135	                ("High", 1, { levels($0).high },
   136	                 { q, v in
   137	                     var l = levels(q)
   138	                     l.high = max(v, l.low)
   139	                     return .levels(range, .set(l))
   140	                 }),
   141	                ("Soft", 1, { levels($0).softness },
   142	                 { q, v in var l = levels(q); l.softness = v; return .levels(range, .set(l)) }),
   143	            ]
   144	        }
   145	        var controls: [NSView] = []
   146	        for field in fields {
   147	            let caption = InspectorRowLabel(field.caption)
   148	            caption.font = DS.sans(10)
   149	            caption.setContentCompressionResistancePriority(.required, for: .horizontal)
   150	            controls.append(caption)
   151	            controls.append(
   152	                OptionFieldControl(
   153	                    width: 41, unit: range == .hue ? "°" : "", decimals: range == .hue ? 0 : 2,
   154	                    min: 0, max: field.max,
   155	                    read: { field.get(read()) },
   156	                    write: { [weak binding] value in
   157	                        binding?.apply(name, ops(field.put(read(), value)))
   158	                    },
   159	                    enabled: on,
   160	                    onEdit: { [weak binding] in binding?.edited() }))
   161	        }
   162	        return inspectorRow(nil, controls, binding: binding, writes: ops(.reset))
   163	    }
   164	}
    }
}

extension ColorQualifier {
    /// The chroma below which a pick has no hue (GR-13's guard's full point).
    static let pickChroma = 0.06

    /// What a pick of `s` writes (owner choice 8): hue and saturation on and
    /// centred on the pixel — a range already on keeps its width and
    /// softness; one off takes hue width 30° softness 15° and saturation
    /// ±0.15 softness 0.1 — and luma re-centred only if already on. A level
    /// range that would cross 0 or 1 is SHIFTED back inside with its width
    /// kept, so the pixel stays inside. A pixel with C below 0.06 turns hue
    /// off; Invert is unchanged.
    func picked(_ s: QualifierSample) -> ColorQualifierPatch {
        var patch = ColorQualifierPatch()
        if s.chroma < Self.pickChroma {
            patch.hue = .off
        } else {
            let width = hue?.width ?? 30
            let softness = hue?.softness ?? 15
            let center = min(max(s.hue, 0), 360)
            patch.hue = .set(QualifierHue(center: center, width: width, softness: softness))
        }
        let saturated = saturation ?? QualifierLevels(low: 0, high: 0.3, softness: 0.1)
        patch.saturation = .set(Self.centred(saturated, on: s.saturation))
        if let luma {
            patch.luma = .set(Self.centred(luma, on: s.luma))
        }
        return patch
    }

    /// `range` moved so its middle is `value`, its width and softness kept,
    /// then shifted back inside 0…1 whole.
    static func centred(_ range: QualifierLevels, on value: Double) -> QualifierLevels {
        let width = min(max(range.high - range.low, 0), 1)
        var low = value - width / 2
        low = min(max(low, 0), 1 - width)
        return QualifierLevels(low: low, high: min(low + width, 1), softness: range.softness)
    }
}

    /// The row's items, in order: "Remove from action N" on a keyed row, "Go
    /// to action M" on a ◇ row, then — for a row with a default — "Set end
    /// value to default" with an action selected on a row that animates, else
    /// "Reset to default", disabled while the row already holds it. Nil when
    /// there would be no item.
    func contextMenu() -> NSMenu? {
        let menu = NSMenu()
        menu.autoenablesItems = false
        let binding = gutter.binding
        if gutter.isKeyed, let number = binding?.selectedActionNumber {
            add("Remove from action \(number)", #selector(removeFromAction(_:)), to: menu)
        }
        if case .other(let number) = gutter.mark {
            add("Go to action \(number)", #selector(goToAction(_:)), to: menu)
        }
        if let rowDefault = gutter.default {
            let atEnd = binding?.selectedAction != nil && gutter.animates
            let item = add(
                atEnd ? "Set end value to default" : "Reset to default",
                #selector(resetToDefault(_:)), to: menu)
            item.isEnabled = rowDefault.differs()
        }
        return menu.items.isEmpty ? nil : menu
    }

    @discardableResult
    private func add(_ title: String, _ action: Selector, to menu: NSMenu) -> NSMenuItem {
        let item = NSMenuItem(title: title, action: action, keyEquivalent: "")
        item.target = self
        menu.addItem(item)
        return item
    }

