     9	use serde_json::{json, Map, Value};
    10	
    11	use crate::actions::MAX_PATCH_DEPTH;
    12	use crate::edit_action_graphic::GRAPHIC_NOT_KEYED_OFF;
    13	use crate::model::{AudioProps, ShapeProps, TextProps, VideoProps};
    14	use crate::patch::{check_group_patch, merge_group, unknown_key, Group};
    15	
    16	/// Removes from `value` every key the incoming `patch` set to `null` —
    17	/// `set_action_end`'s delete rule (spec §6). Only keys the patch mentions
    18	/// are touched, so a `null` that was already in the end patch (animating a
    19	/// shadow away, say) survives untouched. `shift_remove`, because under
    20	/// `preserve_order` `Map::remove` swaps the last key into the hole.
    21	pub(crate) fn prune_removed(value: &mut Value, patch: &Value, depth: u32) {
    22	    let Value::Object(patched) = patch else {
    23	        return;
    24	    };
    25	    let Value::Object(target) = value else {
    26	        return;
    27	    };
    28	    if depth >= MAX_PATCH_DEPTH {
    29	        return;
    30	    }
    31	    for (key, sub) in patched {
    32	        if sub.is_null() {
    33	            target.shift_remove(key);
    34	        } else if let Some(slot) = target.get_mut(key) {
    35	            prune_removed(slot, sub, depth + 1);
    36	        }
    37	    }
    38	}
