    static func setActionEndRaw(
        clip: UInt32, action: UInt32, patch: Any, off: [String] = [], schema: Any? = nil
    ) -> ReelOp {
        var a = OpArgs()
        a.put("clip", clip)
        a.put("action", action)
        a.put("patch", patch)
